import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double for the pricing downstream (unit prices in euros).
const prices = { A: 10, B: 25, C: 0.1, D: 33.33, E: 101, F: 100, G: 100.5 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalFor = async (items) => (await (await post({ items })).json()).total

test('POST /orders 201: returns id, items and total for a small order (no discount)', async () => {
  calls.length = 0
  const res = await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.deepEqual(body, { id: body.id, items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }], total: 45 })
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(calls, ['A', 'B'])
})

test('POST /orders ids are sequential strings and the order is retrievable', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
  const got = await fetch(`${base}/orders/${a.id}`)
  assert.equal(got.status, 200)
  assert.deepEqual(await got.json(), a)
})

test('discount: exactly 100 gets no discount, threshold is strictly > 100', async () => {
  assert.equal(await totalFor([{ sku: 'F', qty: 1 }]), 100)
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('discount: 10% off the whole total once it exceeds 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)   // 110 -> 99
  assert.equal(await totalFor([{ sku: 'A', qty: 20 }]), 180)  // 200 -> 180
  assert.equal(await totalFor([{ sku: 'A', qty: 100 }]), 900) // 1000 -> 900
})

test('discount: cliff at the threshold makes a bigger order cheaper than a smaller one', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — the 10% applies to the whole total,
  // so 101 EUR (-> 90) costs less than 100 EUR (-> 100).
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 90)
  assert.ok((await totalFor([{ sku: 'E', qty: 1 }])) < (await totalFor([{ sku: 'F', qty: 1 }])))
})

test('total is floored to whole euros, never rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — cents are dropped (Math.floor), so
  // totals are integers and fractional prices lose up to 1 EUR.
  assert.equal(await totalFor([{ sku: 'G', qty: 1 }]), 90)    // 100.5 -> 90.45 -> 90
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 33)    // 33.33 -> 33
  assert.equal(await totalFor([{ sku: 'C', qty: 3 }]), 0)     // 0.30000000000000004 -> 0
  assert.equal(await totalFor([{ sku: 'D', qty: 4 }]), 133 - 13) // 133.32 -> 119.988 -> 119
})

test('quantities are not validated', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — negative qty yields a negative total
  // and a missing qty yields NaN, serialised as null.
  const neg = await post({ items: [{ sku: 'A', qty: -3 }] })
  assert.equal(neg.status, 201)
  assert.equal((await neg.json()).total, -30)
  const missing = await post({ items: [{ sku: 'A' }] })
  assert.equal(missing.status, 201)
  assert.equal((await missing.json()).total, null)
